using System;
using System.Linq;
using System.Text;

using LinqToDB;
using LinqToDB.CodeModel;
using LinqToDB.DataModel;
using LinqToDB.Metadata;
using LinqToDB.Naming;
using LinqToDB.Scaffold;
using LinqToDB.Schema;

namespace Tests.Scaffold.Harness
{
	public enum ScaffoldLanguage
	{
		CSharp,
		FSharp,
	}

	/// <summary>
	/// Source code, generated by the current scaffolder from <see cref="TestSchema"/>.
	/// </summary>
	/// <param name="Options">Options after scaffolder applied language restrictions.</param>
	public sealed record GeneratedSource(string Name, ScaffoldLanguage Language, ProviderProfile Profile, ScaffoldOptions Options, SourceCodeFile[] Files)
	{
		public string Namespace => Options.CodeGeneration.Namespace!;

		public string ContextClassName => Options.DataModel.ContextClassName!;

		public string Code => string.Join("\n", Files.Select(static f => f.Code));
	}

	public static class Generator
	{
		public static ILanguageProvider GetLanguage(ScaffoldLanguage language)
			=> language == ScaffoldLanguage.CSharp ? LanguageProviders.CSharp : LanguageProviders.FSharp;

		/// <summary>
		/// Runs scaffolder pipeline (data model load, code model generation, source generation).
		/// </summary>
		/// <param name="name">Case name. Used for namespace and assembly name, so must be unique per compiled model.</param>
		public static GeneratedSource Generate(
			string                   name,
			ScaffoldLanguage         language,
			ProviderProfile          profile,
			TestSchema               schema,
			Action<ScaffoldOptions>? configure    = null,
			ScaffoldInterceptors?    interceptors = null,
			TestTypeMappings?        typeMappings = null)
		{
			var options = ScaffoldOptions.Default();

			options.DataModel.ContextClassName = "TestDataContext";
			options.CodeGeneration.Namespace   = "Gen." + ToIdentifier(name);

			configure?.Invoke(options);

			var languageProvider = GetLanguage(language);
			var scaffolder       = new Scaffolder(languageProvider, HumanizerNameConverter.Instance, options, interceptors);
			var dataModel        = scaffolder.LoadDataModel(schema, (typeMappings ?? profile.CreateTypeMappings()).WithParser(languageProvider.TypeParser));
			var sqlBuilder       = profile.DataProvider.CreateSqlBuilder(profile.DataProvider.MappingSchema, new DataOptions());

			var files = scaffolder.GenerateCodeModel(
				sqlBuilder,
				dataModel,
				MetadataBuilders.GetMetadataBuilder(languageProvider, options.DataModel.Metadata),
				new ProviderSpecificStructsEqualityFixer(languageProvider));

			return new GeneratedSource(name, language, profile, options, scaffolder.GenerateSourceCode(dataModel, files));
		}

		internal static string ToIdentifier(string name)
		{
			var sb = new StringBuilder(name.Length);

			foreach (var c in name)
				sb.Append(char.IsAsciiLetterOrDigit(c) ? c : '_');

			if (sb.Length == 0 || char.IsAsciiDigit(sb[0]))
				sb.Insert(0, '_');

			return sb.ToString();
		}
	}
}
